def names(k):return m.names(k)+EXTRA+[f'prefix{j+1}_{v}' for j in range(k) for v in EXTRA]


def extra(d,i,cc):
    cc=np.asarray(cc,int);self=d['role_history'][i,cc];partners=d['partners'][i,cc]
    other=np.full_like(self,np.nan);known=partners>=0;other[known]=d['role_history'][i,partners[known]]
    return np.column_stack([self,other])


def features(d,i,cc,first=None,second=None):
    parts=[m.features(d,i,cc,first,second),extra(d,i,cc)]
    if first is not None:parts.append(extra(d,i,first))
    if second is not None:parts.append(extra(d,i,second))
    a=np.column_stack(parts).astype(np.float32);assert a.shape[1]==len(names(int(first is not None)+int(second is not None)));return a

